import { createServer, type Server } from "node:http";
import { expect, test, type Frame, type Page } from "@playwright/test";
import { E2E_SAR_HOME } from "../playwright.config";

// Live template preview, for real: a template generated by the actual
// SaveAllResources CLI, previewed with its actual runtime (build.mjs) in a
// separate local process, shown in a sandboxed iframe. Editing a section,
// changing a brand colour and updating page content each show up in the
// preview. The captured site is a small TEST FIXTURE served by this test.

test.describe.configure({ mode: "serial" });
test.skip(!E2E_SAR_HOME, "SaveAllResources is not installed next to Web (set SAR_HOME)");

const html = (title: string, body: string) => `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><title>${title} · Preview Bakery</title><link rel="stylesheet" href="/css/site.css"></head>
<body><header class="site-header"><nav><a href="/">Home</a> <a href="/menu/">Menu</a></nav></header>
<main>${body}</main><footer class="site-footer"><p>Preview Bakery</p></footer></body></html>`;
const SITE: Record<string, [string, string]> = {
  "/": ["text/html", html("Home", `<section class="hero"><h1>Fresh bread daily</h1><p>Sourdough and rye, baked every morning.</p><a class="button" href="/menu/">See the menu</a></section><section class="contact"><h2>Order ahead</h2><form action="https://orders.example.invalid/submit" method="post"><input name="email"><button>Send</button></form></section>`)],
  "/menu/": ["text/html", html("Menu", `<section><h1>Our menu</h1><ul><li>Sourdough</li><li>Rye</li></ul></section>`)],
  "/css/site.css": ["text/css", `:root { --brand: #b45309; }\nbody { font-family: Georgia, serif; color: #1f2937; background: #fffbeb; }\nh1 { color: #b45309; }\n.button { background: #b45309; color: #ffffff; }\n`],
};

let server: Server;
let siteUrl = "";
let previewPage = "";
test.beforeAll(async () => {
  server = createServer((req, res) => {
    const hit = SITE[(req.url ?? "/").split("?")[0]];
    if (!hit) return res.writeHead(404).end("not found");
    res.writeHead(200, { "Content-Type": hit[0] }).end(hit[1]);
  });
  await new Promise<void>((r) => server.listen(0, "127.0.0.1", r));
  const a = server.address();
  siteUrl = `http://127.0.0.1:${typeof a === "object" && a ? a.port : 0}/`;
});
test.afterAll(() => new Promise<void>((r) => server.close(() => r())));

async function generate(page: Page, name: string, authority: "client" | "study") {
  await page.goto("/projects/new");
  await page.getByLabel("Client or business name").fill(name);
  await page.getByLabel("Project name").fill(`${name} project`);
  await page.getByRole("button", { name: "Create project and start brief" }).click();
  await expect(page).toHaveURL(/\/brief$/);
  await page.goto(page.url().replace(/\/brief$/, ""));
  await page.waitForLoadState("networkidle");
  await page.getByLabel(/^Website URL/).fill(siteUrl);
  if (authority === "client") {
    await page.getByLabel(/Client-owned/).check();
    await page.getByLabel(/^Authorised by/).fill("Test owner, written permission 2026-10-02");
  }
  await page.getByText("Capture settings").click();
  await page.getByLabel("Max pages").fill("2");
  await page.getByRole("button", { name: "Generate Website Template" }).click();
  await expect(page.getByTestId("template-pipeline")).toHaveAttribute("data-status", /waiting|completed/, { timeout: 300_000 });
  await page.getByRole("link", { name: "Preview and edit template" }).click();
  await expect(page).toHaveURL(/\/templates\/tpl_/);
}
const previewFrame = async (page: Page): Promise<Frame> => {
  await expect(page.locator('iframe[title="Template preview"]')).toBeVisible();
  let frame: Frame | undefined;
  // The newest preview frame (each rebuild replaces the iframe).
  await expect.poll(() => (frame = page.frames().filter((f) => f.url().startsWith("http://127.0.0.1:") && !f.isDetached()).at(-1))?.url() ?? "", { timeout: 15_000 }).toMatch(/^http:\/\/127\.0\.0\.1:/);
  await frame!.waitForLoadState();
  return frame!;
};
async function rebuilt(page: Page, before: number) {
  const state = page.getByTestId("preview-state");
  await expect.poll(async () => Number(await state.getAttribute("data-build")), { timeout: 30_000 }).toBeGreaterThan(before);
  await expect(state).toHaveAttribute("data-state", "ready");
}
const buildOf = async (page: Page) => Number(await page.getByTestId("preview-state").getAttribute("data-build"));

test("start the preview of a real generated template; its own runtime builds it into an isolated iframe", async ({ page, request }) => {
  test.setTimeout(420_000);
  await generate(page, "Preview Client", "client");
  previewPage = page.url();
  await expect(page.getByText(/· editable$/)).toBeVisible();
  await page.getByRole("button", { name: "Start preview" }).click();
  await expect(page.getByTestId("preview-state")).toHaveAttribute("data-state", "ready", { timeout: 60_000 });
  const frame = await previewFrame(page);
  await expect(frame.locator("h1").first()).toHaveText("Fresh bread daily");
  // The template's own stylesheets load inside the sandboxed frame (not just its HTML).
  await expect.poll(() => frame.evaluate(() => getComputedStyle(document.querySelector("h1")!).color).catch(() => "")).toBe("rgb(180, 83, 9)"); // h1 { color: #b45309 } from the captured CSS

  // Isolation: sandboxed frame on another origin; no cookies; no form submissions; no outside calls.
  await expect(page.locator('iframe[title="Template preview"]')).toHaveAttribute("sandbox", "allow-scripts");
  const tab = page.getByRole("link", { name: "Open preview in new tab" });
  const url = (await tab.getAttribute("href"))!;
  expect(url).toMatch(/^http:\/\/127\.0\.0\.1:\d+\/$/);
  expect(await tab.getAttribute("rel")).toContain("noopener");
  const res = await request.get(url);
  expect(res.headers()["set-cookie"]).toBeUndefined();
  expect(res.headers()["content-security-policy"]).toMatch(/form-action 'none'/);
  expect(res.headers()["content-security-policy"]).toMatch(/connect-src 'self'/);
  expect(res.headers()["content-security-policy"]).toMatch(/frame-ancestors [^;]*http:\/\/localhost:\*/);
  // The captured order form cannot reach the original endpoint.
  const outside: string[] = [];
  page.on("request", (r) => r.url().includes("orders.example.invalid") && outside.push(r.url()));
  await frame.locator("form button").first().click().catch(() => {});
  await page.waitForTimeout(500);
  expect(outside).toEqual([]);

  // Pages and viewports.
  await page.getByLabel("Page", { exact: true }).selectOption("menu/index.html");
  await expect.poll(async () => (await previewFrame(page)).url()).toMatch(/\/menu\/(index\.html)?$/);
  await expect((await previewFrame(page)).locator("h1").first()).toHaveText("Our menu");
  await page.getByRole("button", { name: "Mobile" }).click();
  await expect(page.locator('iframe[title="Template preview"]')).toHaveAttribute("data-viewport", "mobile");
  expect((await page.locator('iframe[title="Template preview"]').boundingBox())!.width).toBeLessThanOrEqual(392);
  await page.getByRole("button", { name: "Desktop" }).click();
  await page.getByLabel("Page", { exact: true }).selectOption({ index: 0 });
});

test("editing a section, changing a brand colour and updating page content each change the preview", async ({ page }) => {
  test.setTimeout(180_000);
  await page.goto(previewPage);
  await page.waitForLoadState("networkidle");
  await expect(page.getByTestId("preview-state")).toHaveAttribute("data-state", "ready", { timeout: 30_000 });

  // 1. A section's text.
  let before = await buildOf(page);
  const heading = page.locator('form[aria-labelledby="content-edit-heading"] input[value="Fresh bread daily"]');
  await heading.fill("Warm loaves, edited live");
  await page.getByRole("button", { name: "Save page" }).click();
  await expect(page.getByRole("status").filter({ hasText: "Page saved." })).toBeVisible();
  await rebuilt(page, before);
  await expect((await previewFrame(page)).locator("h1").first()).toHaveText("Warm loaves, edited live");

  // 2. A brand colour: the template's own CSS variable changes.
  before = await buildOf(page);
  const colourLabel = (await page.locator('label[for^="color-"]').first().textContent())!;
  const key = colourLabel.replace(/^Colour /, "").trim();
  await page.getByLabel(colourLabel, { exact: true }).fill("#ff0066");
  await page.getByRole("button", { name: "Save brand" }).click();
  await expect(page.getByRole("status").filter({ hasText: "Brand saved." })).toBeVisible();
  await rebuilt(page, before);
  // Read from the reloaded frame once its stylesheets have applied.
  await expect
    .poll(async () => ((await (await previewFrame(page)).evaluate((k) => getComputedStyle(document.documentElement).getPropertyValue(`--sar-color-${k}`).trim(), key).catch(() => "")) as string).toLowerCase(), { timeout: 15_000 })
    .toBe("#ff0066");

  // 3. Page content: the page title.
  before = await buildOf(page);
  await page.getByLabel("Page title").fill("Order fresh bread | Preview Bakery");
  await page.getByRole("button", { name: "Save page" }).click();
  await rebuilt(page, before);
  await expect.poll(async () => (await previewFrame(page)).title()).toBe("Order fresh bread | Preview Bakery");

  // Invalid input is refused, and the preview keeps the last good build.
  await page.getByLabel(colourLabel, { exact: true }).fill("red; background:url(x)");
  await page.getByRole("button", { name: "Save brand" }).click();
  await expect(page.getByRole("alert").filter({ hasText: "Colours are hex values" })).toBeVisible();
});

test("stop and restart the preview process", async ({ page }) => {
  test.setTimeout(120_000);
  await page.goto(previewPage);
  await page.waitForLoadState("networkidle");
  const url = (await page.getByRole("link", { name: "Open preview in new tab" }).getAttribute("href"))!;
  await page.getByRole("button", { name: "Stop" }).click();
  await expect(page.getByTestId("preview-state")).toHaveAttribute("data-state", "stopped");
  await expect(page.locator('iframe[title="Template preview"]')).toHaveCount(0);
  await expect(fetch(url)).rejects.toThrow();
  await page.getByRole("button", { name: "Start preview" }).click();
  await expect(page.getByTestId("preview-state")).toHaveAttribute("data-state", "ready", { timeout: 60_000 });
  // Edits live in the working copy, so they survive a restart.
  await expect((await previewFrame(page)).locator("h1").first()).toHaveText("Warm loaves, edited live");
  await page.getByRole("button", { name: "Restart" }).click();
  await expect(page.getByTestId("preview-state")).toHaveAttribute("data-state", "ready", { timeout: 60_000 });
  await page.getByRole("button", { name: "Stop" }).click();
  await expect(page.getByTestId("preview-state")).toHaveAttribute("data-state", "stopped");
});

test("a study-only template can be previewed but not edited", async ({ page }) => {
  test.setTimeout(420_000);
  await generate(page, "Study Client", "study");
  await expect(page.getByText("read-only (study only)")).toBeVisible();
  await expect(page.getByText(/study-only source: it can be previewed, not edited/)).toBeVisible();
  await expect(page.getByRole("button", { name: "Save brand" })).toHaveCount(0);
  await page.getByRole("button", { name: "Start preview" }).click();
  await expect(page.getByTestId("preview-state")).toHaveAttribute("data-state", "ready", { timeout: 60_000 });
  await expect((await previewFrame(page)).locator("h1").first()).toHaveText("Fresh bread daily");
  await page.getByRole("button", { name: "Stop" }).click();
});
